package com.mechanical.worldgen;

import com.mechanical.Mechanical;
import com.mojang.serialization.MapCodec;

import net.minecraft.core.registries.Registries;
import net.minecraft.world.level.levelgen.feature.Feature;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * Small Stone Age worldgen structures, built block by block by Java features so they adapt to the terrain.
 * Placement (rarity, biomes) is data, generated by scripts/gen_structures.py.
 */
public final class Structures {
    public static final DeferredRegister<MapCodec<? extends Feature>> FEATURE_TYPES = DeferredRegister.create(Registries.FEATURE_TYPE, Mechanical.MODID);

    static {
        FEATURE_TYPES.register("abandoned_campsite", () -> AbandonedCampsite.CODEC);
        FEATURE_TYPES.register("hunters_lean_to", () -> HuntersLeanTo.CODEC);
        FEATURE_TYPES.register("bear_den", () -> BearDen.CODEC);
        FEATURE_TYPES.register("standing_stones", () -> StandingStones.CODEC);
        FEATURE_TYPES.register("burial_mound", () -> BurialMound.CODEC);
        FEATURE_TYPES.register("fishing_camp", () -> FishingCamp.CODEC);
        FEATURE_TYPES.register("flint_quarry", () -> FlintQuarry.CODEC);
        FEATURE_TYPES.register("mammoth_bone_hut", () -> MammothBoneHut.CODEC);
        FEATURE_TYPES.register("hermits_hut", () -> HermitsHut.CODEC);
        // small decorations (scripts/gen_decorations.py)
        FEATURE_TYPES.register("glacial_erratic", Boulder.ERRATIC::codec);
        FEATURE_TYPES.register("mossy_boulder", Boulder.MOSSY::codec);
        FEATURE_TYPES.register("sandstone_boulder", Boulder.SANDSTONE::codec);
        FEATURE_TYPES.register("cairn", () -> Cairn.CODEC);
        FEATURE_TYPES.register("balanced_rock", () -> BalancedRock.CODEC);
        FEATURE_TYPES.register("rune_stone", () -> RuneStone.CODEC);
        FEATURE_TYPES.register("stone_head", () -> StoneHead.CODEC);
        FEATURE_TYPES.register("animal_carving", () -> AnimalCarving.CODEC);
        FEATURE_TYPES.register("shrine_statue", () -> ShrineStatue.CODEC);
        FEATURE_TYPES.register("trail", () -> Trails.CODEC);
        FEATURE_TYPES.register("bog_oak_logs", () -> BogOakLogs.CODEC); // scripts/gen_earth.py
        FEATURE_TYPES.register("cave_paintings", CaveFinds.PAINTINGS::codec); // scripts/gen_caves.py
        FEATURE_TYPES.register("tool_cache", CaveFinds.TOOL_CACHE::codec);
    }

    public static void init() {}

    private Structures() {}
}
